/**
 * The content pack. The engine imports content only through this module.
 *
 * PLACEHOLDER CONTENT lives in this folder. See docs/REPLACING_CONTENT.md for how to
 * replace it and docs/PLACEHOLDERS.md (generated by `npm run placeholders`) for the
 * full list of placeholder records and the design-doc slot each one fills.
 */
import { ITEMS } from './items';
import { MONSTERS } from './monsters';
import { BOSSES } from './bosses';
import { ACTS, ROUTES, SLAYER_MASTERS } from './acts';
import { PRAYERS, SPELLBOOKS, SPELLS } from './prayers';
import { BOONS, OMENS, RELICS } from './powers';
import { GATHER_ROOMS, HUB_FEATURES, PETS, RUN_TASKS, SLAYER_UNLOCKS, STARTING_KITS } from './hub';
import { SKILLS } from './skills';
import { TERMS, TERMS_PLACEHOLDERS } from './terms';
import type {
  ActDef,
  BoonDef,
  BossDef,
  Focus,
  GatherRoomDef,
  HubFeatureDef,
  ItemDef,
  MonsterDef,
  OmenDef,
  PetDef,
  PrayerDef,
  RelicDef,
  RouteDef,
  RunTaskDef,
  SkillDef,
  SkillId,
  SlayerMasterDef,
  SlayerUnlockDef,
  SpellDef,
  SpellbookDef,
  StartingKit,
} from './types';

function index<T extends { id: string }>(list: T[], kind: string): Map<string, T> {
  const map = new Map<string, T>();
  for (const entry of list) {
    if (map.has(entry.id)) throw new Error(`Duplicate ${kind} id: ${entry.id}`);
    map.set(entry.id, entry);
  }
  return map;
}

const itemMap = index(ITEMS, 'item');
const monsterMap = index<MonsterDef>([...MONSTERS, ...BOSSES], 'monster');
const bossMap = index(BOSSES, 'boss');
const actMap = index(ACTS, 'act');
const routeMap = index(ROUTES, 'route');
const prayerMap = index(PRAYERS, 'prayer');
const spellMap = index(SPELLS, 'spell');
const spellbookMap = index(SPELLBOOKS, 'spellbook');
const relicMap = index(RELICS, 'relic');
const omenMap = index(OMENS, 'omen');
const boonMap = index(BOONS, 'boon');
const featureMap = index(HUB_FEATURES, 'hub feature');
const petMap = index(PETS, 'pet');
const taskMap = index(RUN_TASKS, 'task');
const masterMap = index(SLAYER_MASTERS, 'slayer master');
const slayerUnlockMap = index(SLAYER_UNLOCKS, 'slayer unlock');
const skillMap = new Map<SkillId, SkillDef>(SKILLS.map((s) => [s.id, s]));
const gatherMap = new Map<string, GatherRoomDef>(GATHER_ROOMS.map((g) => [g.id, g]));

function must<T>(map: Map<string, T>, id: string, kind: string): T {
  const v = map.get(id);
  if (!v) throw new Error(`Unknown ${kind}: ${id}`);
  return v;
}

export const C = {
  items: ITEMS,
  monsters: MONSTERS,
  bosses: BOSSES,
  acts: ACTS,
  routes: ROUTES,
  prayers: PRAYERS,
  spells: SPELLS,
  spellbooks: SPELLBOOKS,
  relics: RELICS,
  omens: OMENS,
  boons: BOONS,
  hub: HUB_FEATURES,
  pets: PETS,
  tasks: RUN_TASKS,
  slayerMasters: SLAYER_MASTERS,
  slayerUnlocks: SLAYER_UNLOCKS,
  skills: SKILLS,
  kits: STARTING_KITS,
  gatherRooms: GATHER_ROOMS,
  terms: TERMS,
  termPlaceholders: TERMS_PLACEHOLDERS,

  item: (id: string): ItemDef => must(itemMap, id, 'item'),
  hasItem: (id: string) => itemMap.has(id),
  monster: (id: string): MonsterDef => must(monsterMap, id, 'monster'),
  boss: (id: string): BossDef => must(bossMap, id, 'boss'),
  isBoss: (id: string) => bossMap.has(id),
  act: (id: string): ActDef => must(actMap, id, 'act'),
  route: (id: string): RouteDef => must(routeMap, id, 'route'),
  prayer: (id: string): PrayerDef => must(prayerMap, id, 'prayer'),
  spell: (id: string): SpellDef => must(spellMap, id, 'spell'),
  spellbook: (id: string): SpellbookDef => must(spellbookMap, id, 'spellbook'),
  relic: (id: string): RelicDef => must(relicMap, id, 'relic'),
  omen: (id: string): OmenDef => must(omenMap, id, 'omen'),
  boon: (id: string): BoonDef => must(boonMap, id, 'boon'),
  feature: (id: string): HubFeatureDef => must(featureMap, id, 'hub feature'),
  pet: (id: string): PetDef => must(petMap, id, 'pet'),
  hasPet: (id: string) => petMap.has(id),
  task: (id: string): RunTaskDef => must(taskMap, id, 'task'),
  slayerMaster: (id: string): SlayerMasterDef => must(masterMap, id, 'slayer master'),
  slayerUnlock: (id: string): SlayerUnlockDef => must(slayerUnlockMap, id, 'slayer unlock'),
  skill: (id: SkillId): SkillDef => {
    const s = skillMap.get(id);
    if (!s) throw new Error(`Unknown skill: ${id}`);
    return s;
  },
  kit: (focus: Focus): StartingKit => {
    const k = STARTING_KITS.find((x) => x.focus === focus);
    if (!k) throw new Error(`No starting kit for ${focus}`);
    return k;
  },
  gatherRoom: (id: string): GatherRoomDef | undefined => gatherMap.get(id),
};

export type ContentPack = typeof C;
export * from './types';
